class TextUtil {
    static int size(Object value) {
        if (value instanceof String s && s.length() > 3) {
            return s.length();
        }
        return -1;
    }
}
public class Main {
    public static void main(String[] args) {
        Object x = "java0";
        int n = TextUtil.size(x);
        if (x instanceof String t && n == t.length()) {
            System.out.print(t.substring(0, 2) + ":" + n);
        } else {
            System.out.print("NG");
        }
    }
}

